class Solution:
    def minimizeTotalPrice(self, n: int, edges: List[List[int]], price: List[int], trips: List[List[int]]) -> int:
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b); adj[b].append(a)
        cnt = [0] * n

        def add_path(a, b):
            par = [-1] * n
            par[a] = a
            stack = [a]
            while stack:
                u = stack.pop()
                if u == b:
                    break
                for v in adj[u]:
                    if par[v] == -1:
                        par[v] = u
                        stack.append(v)
            u = b
            while True:
                cnt[u] += 1
                if u == a:
                    break
                u = par[u]

        for a, b in trips:
            add_path(a, b)

        import sys
        sys.setrecursionlimit(10000)
        def dfs(u, p):
            half = cnt[u] * price[u] // 2
            full = cnt[u] * price[u]
            for v in adj[u]:
                if v != p:
                    ch = dfs(v, u)
                    half += ch[0]
                    full += min(ch)
            return half, full

        return min(dfs(0, -1))

