class Solution {
public:
    int minimizeTotalPrice(int n, vector<vector<int>>& edges, vector<int>& price,
                           vector<vector<int>>& trips) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        vector<long long> cnt(n, 0);
        auto addPath = [&](int a, int b) {
            vector<int> par(n, -1);
            par[a] = a;
            vector<int> st{a};
            while (!st.empty()) {
                int u = st.back(); st.pop_back();
                if (u == b) break;
                for (int v : adj[u]) if (par[v] == -1) { par[v] = u; st.push_back(v); }
            }
            for (int u = b;; u = par[u]) {
                cnt[u]++;
                if (u == a) break;
            }
        };
        for (auto& t : trips) addPath(t[0], t[1]);
        function<pair<long long,long long>(int,int)> dfs = [&](int u, int p) {
            long long half = (long long)cnt[u] * price[u] / 2;
            long long full = (long long)cnt[u] * price[u];
            for (int v : adj[u]) if (v != p) {
                auto ch = dfs(v, u);
                half += ch.first;
                full += min(ch.first, ch.second);
            }
            return make_pair(half, full);
        };
        auto r = dfs(0, -1);
        return (int)min(r.first, r.second);
    }
};

