class Solution {
    List<List<Integer>> adj;
    long[] cnt;
    int[] price;
    public int minimizeTotalPrice(int n, int[][] edges, int[] price, int[][] trips) {
        this.price = price;
        adj = new ArrayList<>();
        for (int i = 0; i < n; ++i) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        cnt = new long[n];
        for (int[] t : trips) addPath(t[0], t[1]);
        long[] r = dfs(0, -1);
        return (int) Math.min(r[0], r[1]);
    }
    void addPath(int a, int b) {
        int[] par = new int[adj.size()];
        Arrays.fill(par, -1);
        par[a] = a;
        Deque<Integer> st = new ArrayDeque<>();
        st.push(a);
        while (!st.isEmpty()) {
            int u = st.pop();
            if (u == b) break;
            for (int v : adj.get(u)) if (par[v] == -1) { par[v] = u; st.push(v); }
        }
        for (int u = b;; u = par[u]) {
            cnt[u]++;
            if (u == a) break;
        }
    }
    long[] dfs(int u, int p) {
        long half = (long) cnt[u] * price[u] / 2;
        long full = (long) cnt[u] * price[u];
        for (int v : adj.get(u)) if (v != p) {
            long[] ch = dfs(v, u);
            half += ch[0];
            full += Math.min(ch[0], ch[1]);
        }
        return new long[]{half, full};
    }
}

