var minimizeTotalPrice = function(n, edges, price, trips) {
    const adj = Array.from({length: n}, () => []);
    for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
    const cnt = new Array(n).fill(0);
    const addPath = (a, b) => {
        const par = new Array(n).fill(-1);
        par[a] = a;
        const st = [a];
        while (st.length) {
            const u = st.pop();
            if (u === b) break;
            for (const v of adj[u]) if (par[v] === -1) { par[v] = u; st.push(v); }
        }
        for (let u = b;; u = par[u]) {
            cnt[u]++;
            if (u === a) break;
        }
    };
    for (const [a, b] of trips) addPath(a, b);
    function dfs(u, p) {
        let half = Math.floor(cnt[u] * price[u] / 2);
        let full = cnt[u] * price[u];
        for (const v of adj[u]) if (v !== p) {
            const ch = dfs(v, u);
            half += ch[0];
            full += Math.min(ch[0], ch[1]);
        }
        return [half, full];
    }
    const r = dfs(0, -1);
    return Math.min(r[0], r[1]);
};
